Следующий код создаст бота Discord, использующий Discord.js v14 с одной командой бан:

1. Сначала необходимо установить пакеты npm:

```bash
npm install discord.js @discordjs/rest discord.hopshino
```

2. Создайте новый файл `index.js` и вставьте в него следующий код:

```javascript
// Import required modules
const { REST } = require('@discordjs/rest');
const { Routes } = require('discord-api-types/v9');
const { Collection } = require('discord.js');
const { Client, Intents } = require('discord.js');

// Import your bot's token and guild ID(s)
const { TOKEN, GUILD_ID } = require('./config.json');

// Create a new Discord client
const client = new Client({ intents: [Intents.FLAGS.GUILDS] });

// Define a collection to store commands
const commands = new Collection();

// Define a function to register commands
function registerCommands() {
  const rest = new REST({ version: '9' }).setToken(TOKEN);

  (async () => {
    try {
      // Register global commands
      await rest.put(Routes.applicationCommands(GUILD_ID), { body: commands.cache.data });

      console.log('Global commands registered successfully.');
    } catch (error) {
      console.error(error);
    }
  })();
}

// Define a command handler
client.commands = new Collection();

const commandFiles = client.commands.map((command) => `${process.cwd()}/commands/${command}.js`);

client.on('ready', () => {
  // Load commands
  commandFiles.forEach((file) => {
    try {
      const command = require(file);
      if (!command.name) throw new Error('Command requires a name property');
      if (typeof command.execute !== 'function') throw new Error('Command must have an execute function');

      client.commands.set(command.name, command);
      commands.set(command.data.name, command.data);
    } catch (error) {
      console.error(`Error loading command: ${file}`, error);
    }
  });

  registerCommands();
});

// Define the ban command
client.on('interactionCreate', async (interaction) => {
  if (!interaction.isSlashCommand()) return;

  const command = client.commands.get(interaction.commandName);
  if (!command) return;

  try {
    await command.execute(interaction);
  } catch (error) {
    console.error(error);
    await interaction.reply({ content: 'There was an error while executing this command!', ephemeral: true });
  }
});

// Login the client
client.login(TOKEN);
```

3. В корневой директории проекта создайте файл `config.json` и добавьте в него следующие свойства:

```json
{
  "TOKEN": "<your bot token here>",
  "GUILD_ID": "<your server ID here>"
}
```

4. Создайте директорию `commands` в корневой директории проекта и внутри неё создайте файл `ban.js`.

5. В файле `ban.js` добавьте следующий код:

```javascript
module.exports = {
  name: 'ban',
  description: 'Bans a member from the server',

  async execute(interaction) {
    const member = interaction.options.getMember('user');

    if (!member) {
      return await interaction.reply({ content: 'Please specify a valid user to ban!', ephemeral: true });
    }

    await interaction.guild.members.ban(member.user);

    await interaction.reply({ content: `${member.user.tag} has been banned.`, ephemeral: true });
  },
};
```

6. Restart your Discord bot, and the ban command should now be available in your Discord server.

Note: Remember to replace `<your bot token here>` and `<your server ID here>` with your actual Discord bot token and server ID, respectively.

